            tracker.moveToStatusOrMark(ticketKey, baAnalysisStatus, 'BA_ANALYSIS', 'PO_REVIEW');

            tracker.postComment(ticketKey, 'h3. ✅ PO Review Complete — Moving to ' + baAnalysisStatus + '\n\n' +
