}

function readJsonFile(filePath) {
    var text = readTextFile(filePath);
    if (!text) {
        return null;
    }
    try {
        return JSON.parse(text);
    } catch (e) {
        console.warn('Failed to parse JSON from ' + filePath + ': ' + (e.message || e));
        return null;
    }
}

function fileNameFromPath(filePath) {
    if (!filePath) {
