        }
    }
    return base;
}

/** Base jobParams with owner/repo */
function baseParams(owner, repo, rules, extra) {
    var jobParams = {
        owner: owner || 'test-org',
        repo: repo || 'test-repo',
        rules: rules || []
    };
    if (extra) {
        for (var k in extra) {
            if (extra.hasOwnProperty(k)) jobParams[k] = extra[k];
        }
    }
